// What the framework hands to a project that adopts it, and what stays its own. Two ways of
// adopting share this list: a copy made with GitHub's "Use this template", which takes later
// releases with `npm run framework:update`, and a project generated by `npm create web-qa`.
//
//   development records  the framework's own history and process: its backlog, changelog,
//                        decisions, community files and repository settings. A project that
//                        adopts the framework keeps its own instead; none of them is shipped.
//   adopter-owned        the example packs and their skills: shipped so the project starts with
//                        a worked example, then the project's own to change or remove
//                        (`npm run remove:app`), so a framework update never touches them.
//   product              every other tracked file.

/** Where the framework's releases are published, as `v<x.y.z>` tags. */
export const FRAMEWORK_REPOSITORY = 'https://github.com/marceloancieta/web-qa-agentic-framework';

/** The framework's own development records, as path prefixes (a trailing `/` is a folder). */
export const DEVELOPMENT_RECORDS = [
  'CHANGELOG.md',
  'CODE_OF_CONDUCT.md',
  'CONTRIBUTING.md',
  'SECURITY.md',
  'docs/adr/',
  'docs/backlog.md',
  'docs/lessons-learned.md',
  'docs/repository-settings.md',
];

/** True when `path` (repository-relative, `/`-separated) is under one of `prefixes`. */
export const isUnder = (path, prefixes) =>
  prefixes.some((prefix) => (prefix.endsWith('/') ? path.startsWith(prefix) : path === prefix));

/** A pack's files and its skill: `apps/<pack>/` and `.claude/skills/<pack>-ui/`. */
export function packPaths(pack) {
  return [`apps/${pack}/`, `.claude/skills/${pack}-ui/`];
}

/** True when `path` belongs to an app pack or a pack skill rather than to the framework. */
export function isAdopterOwned(path) {
  return /^apps\/[^/]+\//.test(path) || /^\.claude\/skills\/[^/]+-ui\//.test(path);
}
